-- V9__seed_distinct_curriculum_course_mappings.sql
-- Fix cross-joined duplicate curriculum course offerings so each degree program has authentic, distinct course mappings

SET FOREIGN_KEY_CHECKS = 0;

DELETE FROM curriculum_courses;
-- -----------------------------------------------------------------------------
-- 5. Seed Curriculum Course Offerings & Term Mappings (Distinct per Degree Program)
-- -----------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE year_level = VALUES(year_level), semester = VALUES(semester), category = VALUES(category), sequence_order = VALUES(sequence_order);

SET FOREIGN_KEY_CHECKS = 1;